head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00014";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — resultDiv, engMandatory1Yn
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.usrTpCd, session.user.dutyGrpTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00014.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrTpCd", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }, { id: "img_35", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }, { id: "c_when_27", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "tr_28", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "tr_30", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "tr_32", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "c_when_36", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "tr_37", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "tr_39", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "tr_41", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "c_when_43", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "tr_44", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "tr_46", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "tr_48", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "img_58", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }, { id: "c_when_50", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "tr_51", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "tr_53", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "tr_55", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "c_when_59", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "tr_60", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "tr_62", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "tr_64", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "c_otherwise_66", fn: function(){ return (!(((dma_pageContext.get("resultDiv") ?? "") === '1') || ((dma_pageContext.get("resultDiv") ?? "") === '2') || ((dma_pageContext.get("resultDiv") ?? "") === '3') || ((dma_pageContext.get("resultDiv") ?? "") === '4') || ((dma_pageContext.get("resultDiv") ?? "") === '5'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("transMessage") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        if ((String(((dma_pageContext.get("engMandatory1Yn") ?? "")) == null ? '' : ((dma_pageContext.get("engMandatory1Yn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("engMandatory1Yn") ?? "")) == null ? '' : ((dma_pageContext.get("engMandatory1Yn") ?? "")))) === 'Y' && '11' === (String(($c.session.getUserInfo("dutyGrpTpCd")) == null ? '' : ($c.session.getUserInfo("dutyGrpTpCd"))).indexOf('$' + '{') >= 0 ? '' : String(($c.session.getUserInfo("dutyGrpTpCd")) == null ? '' : ($c.session.getUserInfo("dutyGrpTpCd"))))) {
            await $c.win.alert("영문공시 1단계 의무화 대상서식 안내 \n ㅇ 영문공시 1단계 의무화 대상법인은 본 서식에 대한 국문공시       제출 후 3영업일 이내에 반드시 영문공시를 제출하여야 합니      다. \n ㅇ 자세한 내용은 거래소 공시규정 및 동 규정 시행세칙의 관련       조문과 거래소 안내사항을 참조하시기 바랍니다.");
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00014.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["dutyGrpTpCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00014' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_16_onclick
 * @description img_16 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_16_onclick = function(e){
    try {
        fn_ViewManualKeyWord(0200000021)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00014.img_16_onclick' }); }
};

/**
 * @method
 * @name img_35_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_35_onclick = function(e){
    try {
        scwin.goList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00014.img_35_onclick' }); }
};

/**
 * @method
 * @name img_58_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_58_onclick = function(e){
    try {
        scwin.goList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00014.img_58_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {void}
 * @hidden N
 */
scwin.goList = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil10100/jldfil10100.xml');
};
